<?php require 'includes.php'; $s=settings(); $db=db_load(); $page_title='Blog | '.$s['clinic_name']; require 'header.php'; ?><section class="page-head"><div class="container"><h1>Health Blog</h1><p>Articles and useful information from our clinic.</p></div></section><section class="section"><div class="container"><div class="blog-grid"><?php if(!$db['blogs']): ?><div class="empty" style="grid-column:1/-1">No blogs published yet.</div><?php else: foreach(array_reverse($db['blogs']) as $b): ?><article class="blog-card"><img src="<?=e($b['image'] ?: 'assets/images/logo.png')?>" alt="<?=e($b['title'])?>"><div class="blog-body"><small><?=e(date_fmt($b['created_at']))?></small><h3><?=e($b['title'])?></h3><p><?=e(substr(strip_tags($b['content']),0,160))?>...</p><a class="btn btn-sm" href="blog-detail.php?id=<?=e($b['id'])?>">Read More</a></div></article><?php endforeach; endif; ?></div></div></section><?php require 'footer.php'; ?>
